function readableFallback(key: string): string {
  const last = key.split(".").pop() ?? key;
  return last
    .replace(/_label$|_placeholder$|_btn$/, "")
    .replace(/_/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .trim();
}

export function getTranslation(lang: Language, key: string, fallback?: string): string {
  const langMap = translations[lang];
  if (langMap && key in langMap) return langMap[key];
  const enMap = translations["en"];
  if (enMap && key in enMap) return enMap[key];
  return fallback ?? readableFallback(key);
}

export function t(key: string, lang: Language, fallback?: string): string {
  return getTranslation(lang, key, fallback);
}
